public async Task<BoardDetailDto> CreateAsync(CreateBoardRequest request)
    {
        new InlineValidator<CreateBoardRequest>
            { v => v.RuleFor(x => x.Name).NotEmpty().MaximumLength(200) }
            .ValidateAndThrow(request);

