                tx.Commit();
                _logger.LogInformation("Board {BoardId} created by user {UserId}", board.Id, userId);
                return BoardTransforms.ToDetailDto(board, BoardRole.Owner, []);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
